<?php
declare(strict_types=1); session_start();
require_once __DIR__.'/../app/Helpers/Database.php'; require_once __DIR__.'/../app/Helpers/Auth.php'; require_once __DIR__.'/../app/Helpers/Csrf.php'; require_once __DIR__.'/../app/Helpers/Response.php';
use SAMS\Helpers\Database; use SAMS\Helpers\Auth; use SAMS\Helpers\Csrf; use SAMS\Helpers\Response;
header('Content-Type: application/json; charset=UTF-8');
try{$u=Auth::requireLogin();$pdo=Database::connection();$cid=(int)($_GET['class_id']??0);$start=(string)($_GET['week_start']??'');if($cid<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))Response::error('Invalid class or date.',422);$end=date('Y-m-d',strtotime($start.' +5 days'));$check=$pdo->prepare($u['role']==='admin'||$u['role']==='counselor'?'SELECT 1 FROM classes WHERE id=? AND is_active=1':'SELECT 1 FROM classes c JOIN teacher_classes tc ON tc.class_id=c.id WHERE c.id=? AND c.is_active=1 AND tc.teacher_id=?');$check->execute($u['role']==='admin'||$u['role']==='counselor'?[$cid]:[$cid,$u['id']]);if(!$check->fetchColumn())Response::error('Forbidden.',403);if($_SERVER['REQUEST_METHOD']==='GET'){$q=$pdo->prepare('SELECT a.student_id,a.attendance_date,a.period,a.status FROM attendance a JOIN students s ON s.id=a.student_id WHERE s.class_id=? AND a.attendance_date BETWEEN ? AND ?');$q->execute([$cid,$start,$end]);Response::success(['attendance'=>$q->fetchAll()]);}if(!Csrf::verify((string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))Response::error('Invalid CSRF token.',419);$b=json_decode((string)file_get_contents('php://input'),true)??[];$sid=(int)($b['student_id']??0);$date=(string)($b['attendance_date']??'');$period=(int)($b['period']??0);$status=(string)($b['status']??'');if($sid<1||$period<1||$period>8||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!in_array($status,['present','absent','late','excused'],true))Response::error('Invalid attendance data.',422);$q=$pdo->prepare('SELECT 1 FROM students WHERE id=? AND class_id=? AND status=\'active\'');$q->execute([$sid,$cid]);if(!$q->fetchColumn())Response::error('Student not found.',404);$q=$pdo->prepare('INSERT INTO attendance(student_id,attendance_date,period,status,recorded_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by),updated_at=CURRENT_TIMESTAMP');$q->execute([$sid,$date,$period,$status,$u['id']]);Response::success();}catch(Throwable $e){Response::error('Server error.',500);}
